/*
Definition of singly linked list:
class ListNode{
    public int data;
    public ListNode next;
    ListNode() { data = 0; next = null; }
    ListNode(int x) { data = x; next = null; }
    ListNode(int x, ListNode next) { data = x; this.next = next; }
}
*/

class Solution {
    public ListNode insertAtKthPosition(ListNode head, int X, int K) {
        //YOUR CODE GOES HERE
        ListNode New = new ListNode(X);
        if(K==1){
          New.next = head;
          return New;
        }
        ListNode curr = head;
        int count = 1;

        while(curr != null){
            if(count == K-1){ 
              New.next = curr.next;
              curr.next = New;
              break;
            }
            curr = curr.next;
            count ++;
        }
        return head;
    }
}
```
